import{_ as r,a as e,b as d,c as a}from"./chunks/image-20261116061532792.C1j-yP-O.js";import{_ as i,o as s,c as o,a2 as p}from"./chunks/framework.CmPiTyN0.js";const f=JSON.parse('{"title":"辅助设备","description":"","frontmatter":{"title":"辅助设备","outline":"deep"},"headers":[],"relativePath":"wiki/equipment.md","filePath":"wiki/equipment.md","lastUpdated":1794811249000}'),n={name:"wiki/equipment.md"};function _(m,t,l,c,g,h){return s(),o("div",null,[...t[0]||(t[0]=[p('<p><a href="./../index.html">← 返回 Wiki 首页</a></p><h2 id="_6-辅助设备" tabindex="-1">6. 辅助设备 <a class="header-anchor" href="#_6-辅助设备" aria-label="Permalink to &quot;6. 辅助设备&quot;">​</a></h2><p>RVP 的辅助设备按骨块模块配置，具有独立耐久和功能状态。设备被击毁后对应功能停止，可通过维修恢复。</p><table tabindex="0"><thead><tr><th>设备</th><th>功能</th></tr></thead><tbody><tr><td>ERA 爆炸反应装甲</td><td>拥有较高的免伤倍率，承担一定伤害后爆炸消失</td></tr><tr><td>APS 主动防护</td><td>按扇区探测并拦截来袭弹药；传感器骨块被击毁后，对应扇区停止拦截</td></tr><tr><td>ECM 主动干扰</td><td>释放后干扰一定范围内的雷达/卫星/无线电制导导弹，同时成为最高辐射源吸引反辐射导弹。电子战机的强效ECM甚至产生虚假信号能干扰战斗机的雷达与RWR</td></tr><tr><td>被动 ECM</td><td>被敌方雷达照射时生成假目标，干扰对方雷达判断；骨块失效后停止生成</td></tr><tr><td>光电干扰机（软杀伤干扰机）</td><td>对进入干扰扇区的 SACLOS 导弹进行干扰，使其偏离攻击弹道</td></tr><tr><td>DIRCM 定向红外对抗</td><td>对 IR、AIR，人在回路导弹以及<strong>SBW</strong>模组的SA18单兵弹实施定向干扰，使其偏离攻击弹道，但是火力通道有限，会被同时来袭的多枚红外导弹突防</td></tr><tr><td>热焰弹/箔条/烟幕</td><td>按载具配置抛洒，各自独立备弹和冷却；热焰弹能干扰IR导弹和AIR导弹；箔条可以干扰雷达制导导弹以及让战机雷达脱锁；烟幕可遮挡激光点，屏蔽红外制导导弹，使得对应导弹失准。</td></tr><tr><td>维修设备</td><td>修复部件和设备；</td></tr></tbody></table><p>设备面板显示辅助设备状态，并可设置维修顺序。ERA 与辅助设备使用独立的维修队列；同骨同时具有 ERA 和其它设备时，按爆反队列捆绑恢复。</p><p><img src="'+r+'" alt="image-20261116060711636"><strong>图6.1 爆炸反应装甲</strong></p><p><img src="'+e+'" alt="image-20261116060854988"></p><p><strong>图6.2 主动防御系统</strong></p><p><img src="'+d+'" alt="image-20261116061357053"><strong>图6.3 DIRCM干扰</strong></p><p><img src="'+a+'" alt="image-20261116061532792"></p><p><strong>图6.4 DIRCM干扰SBW导弹</strong></p><hr>',12)])])}const A=i(n,[["render",_]]);export{f as __pageData,A as default};
